<?php require '../includes/auth.php';require_role('seller');$sid=seller_profile_id(user()['id']);$pdo=db();$statuses=['Pending','Accepted','Rejected','Preparing','Ready for Pickup','Out for Delivery','Delivered','Cancelled'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=post('status');$id=(int)post('id');$order=$pdo->prepare('SELECT so.order_id,so.status seller_status,o.status parent_status FROM seller_orders so JOIN orders o ON o.id=so.order_id WHERE so.id=? AND so.seller_id=?');$order->execute([$id,$sid]);$current=$order->fetch();if(!$current)flash('error','Order was not found.');elseif($current['parent_status']==='Cancelled'||$current['seller_status']==='Cancelled')flash('error','This order was cancelled and can no longer be changed.');elseif(!in_array($status,$statuses,true))flash('error','Invalid order status.');else{$pdo->prepare('UPDATE seller_orders SET status=? WHERE id=? AND seller_id=?')->execute([$status,$id,$sid]);$states=$pdo->prepare('SELECT status FROM seller_orders WHERE order_id=?');$states->execute([$current['order_id']]);$all=$states->fetchAll(PDO::FETCH_COLUMN);$parentStatus=count(array_diff($all,['Rejected','Cancelled']))===0?'Cancelled':(count(array_unique($all))===1&&$all[0]==='Delivered'?'Delivered':($status==='Rejected'?'Pending':$status));if(in_array($parentStatus,['Pending','Accepted','Preparing','Ready for Pickup','Out for Delivery','Delivered','Cancelled'],true))$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$parentStatus,$current['order_id']]);flash('success','Order status updated.');}redirect('seller/orders.php');}$s=$pdo->prepare('SELECT so.*,o.order_number,o.delivery_type,o.created_at,o.status parent_status,u.name buyer_name FROM seller_orders so JOIN orders o ON so.order_id=o.id JOIN users u ON o.buyer_id=u.id WHERE so.seller_id=? ORDER BY o.created_at DESC');$s->execute([$sid]);$orders=$s->fetchAll();$pageTitle='Incoming orders';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">SELLER FULFILLMENT</p><h1>Incoming orders</h1></div><?php foreach($orders as $o):$it=$pdo->prepare('SELECT * FROM order_items WHERE seller_order_id=?');$it->execute([$o['id']]);$locked=$o['parent_status']==='Cancelled'||$o['status']==='Cancelled';?><article class="seller-order"><div><small><?=e($o['order_number'])?> · <?=date('d M, H:i',strtotime($o['created_at']))?></small><h2><?=e($o['buyer_name'])?> <span class="badge <?=status_class($o['status'])?>"><?=e($o['status'])?></span></h2><p><?php foreach($it as $i)echo e($i['product_name']).' × '.$i['quantity'].' kg · ';?></p></div><div><strong>₹<?=number_format($o['subtotal'],2)?></strong><?php if($locked):?><p class="muted">Cancelled orders are locked.</p><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach($statuses as $st):?><option <?=$st===$o['status']?'selected':''?>><?=$st?></option><?php endforeach;?></select><button>Update</button></form><?php endif;?></div></article><?php endforeach;?><?php if(!$orders):?><div class="empty"><h2>No seller orders yet.</h2></div><?php endif;require '../includes/footer.php'; ?>
